const lessons=[{"sentences":[{"speaker":"A","text":"Good afternoon I am calling to arrange an apartment viewing for the property on Green Street.","pauseAfterSeconds":0.2,"position":1,"audioStartSeconds":0,"audioEndSeconds":5.12},{"speaker":"B","text":"Good afternoon we have several openings this week although our schedule fills up quickly.","pauseAfterSeconds":0.2,"position":2,"audioStartSeconds":5.32,"audioEndSeconds":9.72},{"speaker":"A","text":"I finish work at five every day so I would prefer something after that time.","pauseAfterSeconds":0.2,"position":3,"audioStartSeconds":9.92,"audioEndSeconds":14.24},{"speaker":"B","text":"We can easily schedule you for Thursday at five thirty if that suits you.","pauseAfterSeconds":0.2,"position":4,"audioStartSeconds":14.44,"audioEndSeconds":17.88},{"speaker":"A","text":"That time works perfectly because I do not have to work late on Thursday.","pauseAfterSeconds":0.2,"position":5,"audioStartSeconds":18.08,"audioEndSeconds":22.08},{"speaker":"B","text":"Before we confirm I should mention that the street can get quite busy during rush hour.","pauseAfterSeconds":0.2,"position":6,"audioStartSeconds":22.28,"audioEndSeconds":26.68},{"speaker":"A","text":"Is the apartment noisy when the windows are closed because I need a quiet place to sleep?","pauseAfterSeconds":0.2,"position":7,"audioStartSeconds":26.88,"audioEndSeconds":31.68},{"speaker":"B","text":"The double glazing blocks almost all outside sound when they are shut completely.","pauseAfterSeconds":0.2,"position":8,"audioStartSeconds":31.88,"audioEndSeconds":36.2},{"speaker":"A","text":"That is a huge relief since I am a very light sleeper.","pauseAfterSeconds":0.2,"position":9,"audioStartSeconds":36.4,"audioEndSeconds":39.92},{"speaker":"B","text":"The subway station is also just a five minute walk from the front door.","pauseAfterSeconds":0.2,"position":10,"audioStartSeconds":40.12,"audioEndSeconds":43.96},{"speaker":"A","text":"That makes my morning commute to the city center much easier and faster.","pauseAfterSeconds":0.2,"position":11,"audioStartSeconds":44.16,"audioEndSeconds":48.4},{"speaker":"B","text":"Shall I send the confirmation email with the exact address and parking details now?","pauseAfterSeconds":0.2,"position":12,"audioStartSeconds":48.6,"audioEndSeconds":52.92},{"speaker":"A","text":"Yes please send it to my personal email address before this evening.","pauseAfterSeconds":0.2,"position":13,"audioStartSeconds":53.12,"audioEndSeconds":57.12},{"speaker":"B","text":"I have sent the message so please check your inbox in a moment.","pauseAfterSeconds":0.2,"position":14,"audioStartSeconds":57.32,"audioEndSeconds":60.76},{"speaker":"A","text":"I have received it now and I will see you on Thursday evening.","pauseAfterSeconds":0.2,"position":15,"audioStartSeconds":60.96,"audioEndSeconds":64.64},{"speaker":"B","text":"We look forward to showing you around the apartment very soon.","pauseAfterSeconds":0.2,"position":16,"audioStartSeconds":64.84,"audioEndSeconds":68.04}],"questions":[{"prompt":"What is the primary purpose of the telephone call?","options":["to rent an apartment immediately.","to arrange a property viewing.","to complain about street noise."],"answer":"B","evidenceSentence":1,"evidence":"arrange an apartment viewing","explanation":"Người nói gọi điện để sắp xếp lịch đi xem căn hộ."},{"prompt":"When would the caller prefer to visit the apartment?","options":["before five in the morning.","during the lunch break.","after five in the evening."],"answer":"C","evidenceSentence":3,"evidence":"prefer something after that time","explanation":"Người mua nhà muốn đi xem sau giờ làm việc, tức là sau năm giờ chiều."},{"prompt":"What problem does the agent mention about the location?","options":["the street gets busy during rush hour.","the subway station is too far away.","the building needs major repairs."],"answer":"A","evidenceSentence":6,"evidence":"street can get quite busy","explanation":"Nhân viên môi giới đề cập rằng con phố có thể rất đông đúc vào giờ cao điểm."},{"prompt":"Why is the caller worried about street noise?","options":["because they work from home.","because they are a light sleeper.","because they dislike city life."],"answer":"B","evidenceSentence":9,"evidence":"I am a very light sleeper","explanation":"Người mua nhà lo lắng vì họ rất khó ngủ khi có tiếng ồn."},{"prompt":"How close is the nearest subway station?","options":["a ten minute walk.","a five minute walk.","a fifteen minute walk."],"answer":"B","evidenceSentence":10,"evidence":"just a five minute walk","explanation":"Ga tàu điện ngầm cách cửa chính năm phút đi bộ."},{"prompt":"What must the agent do next?","options":["send a confirmation email.","call the landlord again.","cancel the Thursday appointment."],"answer":"A","evidenceSentence":12,"evidence":"send the confirmation email","explanation":"Nhân viên môi giới đồng ý gửi email xác nhận với địa chỉ chính xác."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
